    { "theme": "Calculando probabilidades: teórica e experimental", "curriculumCode": "EF06MA30", "description": "Cálculo da probabilidade de eventos aleatórios expressa em fração, decimal e percentual, comparando o valor teórico com resultados obtidos em experimentos sucessivos.", "materials": ["Dados", "Moedas", "Saquinho com fichas coloridas", "Folha de registro de frequências"], "steps": ["Apresentar um experimento simples, como lançar um dado ou uma moeda.", "Calcular a probabilidade teórica de um evento específico.", "Realizar o experimento repetidas vezes, registrando os resultados obtidos.", "Calcular a probabilidade experimental a partir da frequência observada.", "Comparar a probabilidade teórica com a experimental.", "Expressar as probabilidades encontradas em fração, decimal e percentual."] },
    { "theme": "Os elementos de um gráfico: título, eixos e legendas", "curriculumCode": "EF06MA31", "description": "Identificação dos elementos que compõem diferentes tipos de gráfico, como título, eixos, legendas, fontes e datas, além da diferenciação entre variáveis categóricas e numéricas.", "materials": ["Exemplos de gráficos de jornais ou revistas", "Folha de análise", "Lápis de cor"], "steps": ["Distribuir diferentes gráficos de colunas ou barras para análise em grupos.", "Pedir que identifiquem título, eixos, legenda, fonte e data em cada gráfico.", "Discutir a diferença entre variáveis categóricas e numéricas presentes nos gráficos.", "Comparar gráficos incompletos ou mal elaborados com os completos.", "Propor que cada grupo aponte o que falta em um gráfico incompleto fornecido.", "Socializar as análises feitas por cada grupo."] },
    { "theme": "Interpretando dados da mídia sobre meio ambiente e consumo", "curriculumCode": "EF06MA32", "description": "Leitura e interpretação de tabelas e gráficos veiculados pela mídia sobre temas como meio ambiente, trânsito e consumo responsável, com produção de texto síntese das conclusões.", "materials": ["Reportagens com gráficos e tabelas impressas", "Folha para produção de texto"], "steps": ["Selecionar uma reportagem com gráfico ou tabela sobre tema ambiental ou de consumo.", "Ler coletivamente os dados apresentados na reportagem.", "Discutir em grupos o que os dados revelam sobre o tema.", "Responder a perguntas de interpretação sobre o gráfico ou tabela.", "Produzir um texto curto sintetizando as conclusões encontradas.", "Compartilhar os textos produzidos com a turma."] },
    { "theme": "Planejando uma pesquisa e organizando dados em planilha", "curriculumCode": "EF06MA33", "description": "Planejamento e coleta de dados de uma pesquisa sobre um tema social escolhido pelos estudantes, com registro e representação em planilha eletrônica, tabelas e gráficos.", "materials": ["Computador ou tablet com planilha eletrônica", "Formulário de pesquisa impresso", "Projetor (opcional)"], "steps": ["Definir coletivamente um tema social para a pesquisa.", "Elaborar as perguntas do formulário de pesquisa em grupo.", "Coletar os dados entrevistando colegas ou outras turmas.", "Registrar os dados coletados em uma planilha eletrônica.", "Gerar um gráfico a partir da planilha para representar os resultados.", "Apresentar as conclusões da pesquisa em um texto curto ou exposição oral."] },
    { "theme": "Fluxogramas para representar relações e hierarquias", "curriculumCode": "EF06MA34", "description": "Interpretação e criação de fluxogramas simples que representam relações entre objetos, como conexões entre cidades ou hierarquia de funções em uma organização.", "materials": ["Papel", "Canetinhas", "Exemplos de organogramas e mapas de conexões"], "steps": ["Apresentar um exemplo de fluxograma representando hierarquia, como o organograma de uma empresa.", "Discutir como as setas e níveis indicam relações entre os elementos.", "Propor um novo contexto, como uma rede de estradas entre cidades, para representação.", "Pedir que os alunos construam um fluxograma representando essas relações.", "Trocar os fluxogramas entre grupos para leitura e interpretação.", "Socializar as interpretações e ajustar eventuais erros de representação."] }
